import { Text, View, ImageBackground, StyleSheet, ScrollView, Dimensions, AppRegistry } from 'react-native';
import { useCallback } from 'react';
import { useFonts } from 'expo-font'
import * as SplashScreen from 'expo-splash-screen';
import Categories from "./components/Categories"
import Questions from './components/Questions';
import React, { useState } from 'react';
import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import Create_Category from './components/Create_Category';

const Stack = createNativeStackNavigator();

const navTheme = {
  ...DefaultTheme,
  colors: {
    ...DefaultTheme.colors,
    background: "transparent",
  },
}
export default function App() {
  const [points, setPoints] = useState(0);
  const [cookies, setCookies] = useState(0);

  const [fontsLoaded] = useFonts({
    "Derivia": require("./assets/fonts/Derivia-Regular.otf"),
    "Lazy_dog": require("./assets/fonts/lazy_dog.ttf")
  })
  const onLayoutRootView = useCallback(async () => {
    if(fontsLoaded) {
      await SplashScreen.hideAsync();
    }
  }, [fontsLoaded])

  if(!fontsLoaded) {
    return null;
  }

  return (
    <ImageBackground source={require("./assets/PNG/background.png")}
      style={styles.backgroundImage}>
        <NavigationContainer theme={navTheme}>
              <Stack.Navigator screenOptions={{ headerShown: false }} initialRouteName='Categories'>
                <Stack.Screen name='Categories' component={Categories}  />
                <Stack.Screen name='Questions' component={Questions} initialParams={{ points: points , setPoints: setPoints, 
                  cookies: cookies, setCookies: setCookies }} />
                <Stack.Screen name='create_category' component={Create_Category} />
              </Stack.Navigator>
        </NavigationContainer>
    </ImageBackground>
  );
}

<script src="http://localhost:8097"></script>
const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
  },
  backgroundImage: {
    flex: 1,
    resizeMode: 'contain',
    width: "100%",
    height: "100%"
  }, 
  
  categories: {
    flex: 1
  },
  scrollViewContainer: {
    flex: 1,
  }
});
