import React, { useState, useEffect } from 'react';
import { View, Text, Image, StyleSheet, TouchableOpacity, Timer } from 'react-native';
import Colors from '../Colors';

const Questions = ({ navigation, route }) => {
 const [questions_end, setQuestions_end] = useState(false);
 const { points, setPoints, cookies, setCookies } = route.params
 const checkForCookie = () => {
   setC(parseInt((p + 1) / 5))
   setCookies(parseInt((p + 1) / 5));
 };
 const [p, setP] = useState(points)
 const [c, setC] = useState(cookies)
 const tickPress = () => {
    setP(p => p + 1)
    setPoints(points => points + 1);
    checkForCookie();
    addI()
 };

 
 const addI = () => {
    if(i + 1 < questions.length) {
        setI(i + 1);
        console.log(questions_ids[i])
    } else {
        setQuestions_end(true)
    }
 }
    const getRandomNumber = (n) => {
        return Math.floor(Math.random() * n);
    };
    const [questions_ids, setQuestions_ids] = useState([]);
    const [minutes, setMinutes] = useState(0);
    const [seconds, setSeconds] = useState(0);
    const [questions, setQuestions] = useState([]);
    const [i, setI] = useState(0);
    
 React.useEffect(() => {
    if(route.params?.questions) {
        setQuestions(route.params.questions);
       var nums = Array.from(Array(route.params.questions.length).keys())
       let questions_id = []
       let k = nums.length
       let j = 0;
   
       while (k--) {
           j = Math.floor(Math.random() * (k+1));
           questions_id.push(nums[j]);
           nums.splice(j,1);
       }
       setQuestions_ids(questions_id)
       console.log(questions_ids)
    }}, [route.params.questions])
    useEffect(() => {
        // Uruchamiamy interwał co sekundę
        const interval = setInterval(() => {
          // Zwiększamy sekundy o 1
          setSeconds((prevSeconds) => prevSeconds + 1);
    
          // Jeśli osiągnęliśmy 60 sekund, resetujemy sekundy i zwiększamy minuty
          if (seconds === 59) {
            setSeconds(0);
            setMinutes((prevMinutes) => prevMinutes + 1);
          }
        }, 1000);
    
        // Czyszczenie interwału po zakończeniu komponentu
        return () => clearInterval(interval);
      }, [seconds]);

    const reset = () => {
        setI(0);
        setPoints(0);
        setCookies(0);
        setMinutes(0);
        setSeconds(0);
        setC(0)
        setP(0)
        var nums = Array.from(Array(route.params.questions.length).keys())
       let questions_id = []
       let k = nums.length
       let j = 0;
   
       while (k--) {
           j = Math.floor(Math.random() * (k+1));
           questions_id.push(nums[j]);
           nums.splice(j,1);
       }
       setQuestions_ids(questions_id)
    }

 return (
    <View style={styles.container}>
        <View style={styles.header}>
            <TouchableOpacity style={styles.backImageTouchableOpacity} onPress={() => {
                navigation.navigate("Categories")
            }}>
                <Image source={require('../assets/PNG/back.png')} 
                style={styles.backImage} />
            </TouchableOpacity>
            <Text style={styles.timer}>Time: {minutes}:{seconds < 10 ? '0' : ''}{seconds}</Text>
            <TouchableOpacity onPress={reset} style={styles.backImageTouchableOpacity}>
                <Image source={require('../assets/PNG/reset.png')} 
                style={styles.backImage} />
            </TouchableOpacity>
        </View>
        {questions_end ? <View style={styles.content}>
        <Text style={styles.text}>
            Skończyły się pytania
            </Text>
            <View style={styles.buttonContainer}>
                <TouchableOpacity onPress={() => {
                navigation.navigate("Categories")
            }}>
                    <Image
                    style={styles.tickImage}
                    source={require('../assets/PNG/back.png')}
                    />
                </TouchableOpacity>
                <TouchableOpacity onPress={() => {reset(); setQuestions_end(false)}}>
                    <Image
                    style={styles.crossImage}
                    source={require('../assets/PNG/reset.png')}
                    />
                </TouchableOpacity>
            </View>
        </View> : 
        <View style={styles.content}>
            <View style={styles.undoQuestion}>
                <TouchableOpacity onPress={() => {if(i > 0) setI(i - 1)}}>
                    <Image style={styles.undoQuestionImage} source={require('../assets/PNG/back.png')} />
                </TouchableOpacity>
            </View>

            <Text style={styles.text}>
            {questions_ids.length > 0 ? questions[questions_ids[i]] : ""}
            </Text>
            <View style={styles.buttonContainer}>
                <TouchableOpacity onPress={tickPress}>
                    <Image
                    style={styles.tickImage}
                    source={require('../assets/PNG/tick.png')}
                    />
                </TouchableOpacity>
                <TouchableOpacity onPress={addI}>
                    <Image
                    style={styles.crossImage}
                    source={require('../assets/PNG/cross.png')}
                    />
                </TouchableOpacity>
            </View>
        </View>}
        <View style={styles.bottom}>
            <Text style={styles.pointsText}>POINTS: {p}</Text>
            <View style={styles.cookieContainer}>
                <Image source={require('../assets/PNG/nadgryzione_ciasteczko.png')}
                    style={styles.cookie} />
                <Text style={styles.cookiesText}>{c}</Text>
            </View>
        </View>
    </View>
 );
};

const styles = StyleSheet.create({
 undoQuestion: {
    position: "absolute",
    top: 10,
    left: 10,
    borderWidth: 2,
    backgroundColor: Colors.plum,
    borderRadius: 5
 },
 undoQuestionImage: {
    height: "40px",
    width: "40px",
   resizeMode: "contain",
 },
 container: {
    flex: 1,
    width: "100%",
    alignItems: 'center',
 },
 content: {
    marginVertical: 7,
    flex: 1,
    backgroundColor: Colors.pink_card,
    width: "90%",
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 15,
    justifyContent: "space-evenly",
    padding: "20px",
 },
 text: {
    fontSize: "9vw",
    textAlign: "center",
    fontFamily: "Derivia",
    marginBottom: "100px"
 },
 buttonContainer: {
    flexDirection: 'row',
    justifyContent: 'space-evenly',
    width: "100%",
    bottom: "50px",
    position: "absolute"
 },
 tickImage: {
    width: 100,
    height: 100,
 },
 crossImage: {
    width: 100,
    height: 100,
 },
 backImage: {
    height: "100%",
    width: "100%",
   resizeMode: "contain"
 },
 backImageTouchableOpacity: {
    width: "18%",
    height: "100%",
    borderWidth: 2,
    backgroundColor: Colors.plum,
    borderRadius: 5
 },
 pointsText: {
    fontSize: 24,
    marginTop: 10,
 },
 cookiesText: {
    fontSize: 24,
    marginTop: 10,
 },
 header: {
    width: "90%",
    backgroundColor: "#fff",
    height: "10%",
    justifyContent: "center",
    borderRadius: 7,
    flexDirection: "row",
    justifyContent: "space-between",
    padding: 4,
    alignItems: "center"
 },
 timer: {
    textAlignVertical: "center",
    textTransform: "uppercase",
    fontSize: "6vw"
 },
 bottom: {
    flexDirection: "row",
    justifyContent: "space-evenly",
    width: "100%",
    backgroundColor: "#fff",
    borderRadius: 10,
    height: "10%",
    alignItems: "center"
 },
 cookie: {
    width: 60,
    height: 60,
    marginHorizontal: 10
 },
 cookieContainer: {
    flexDirection: "row"
 }
});

export default Questions;